/* Stage usage table for the IPv6 sparse-node codec.
 *
 * Reads a binary request on stdin:
 *     u32 magic, u32 max_stride, u32 n,
 *     then n records of { u8 address[16] (network order), u8 length }.
 * Writes 129*129 little endian u64 values on stdout: F[b][e] is the exact
 * number of bits used by a stage that covers the bit interval (b, e].
 *
 * The layout of a stage depends only on the cut pair (b, e) and the FIB, so
 * the whole table is computed with one bottom-up pass over the prefix trie.
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAGIC 0x31424654u
#define MAXN 300000
#define MAXLEV 129
#define MAXW 4096
#define HSIZE (1u << 20)

typedef struct {
    int32_t parent;
    int32_t child[2];
    int32_t depth;
    uint8_t marked;
} Node;

static Node *nodes;
static int32_t node_count;
static int32_t *htab;
static int32_t *hkey;
static uint32_t hmask = HSIZE - 1;

static uint64_t usage[MAXLEV][MAXLEV];

static uint64_t cntbuf[2][33][MAXW];
static uint64_t livebuf[2][33][MAXW];
static uint64_t mbuf[2][MAXW];

static int32_t *level_nodes;
static int32_t level_start[MAXLEV + 2];
static int32_t level_count[MAXLEV + 2];
static int32_t child_lo[MAXLEV][MAXW];
static int32_t child_hi[MAXLEV][MAXW];

static inline uint64_t align8(uint64_t x) { return (x + 7u) & ~(uint64_t)7u; }
static inline uint64_t align64(uint64_t x) { return (x + 63u) & ~(uint64_t)63u; }

static inline uint32_t hash_key(int32_t key)
{
    uint32_t x = (uint32_t)key * 2654435761u;
    x ^= x >> 15;
    x *= 2246822519u;
    x ^= x >> 13;
    return x & hmask;
}

static int32_t find_or_add(int32_t parent, int bit)
{
    int32_t key = (parent << 1) | bit;
    uint32_t h = hash_key(key);
    while (htab[h]) {
        if (hkey[h] == key)
            return htab[h] - 1;
        h = (h + 1) & hmask;
    }
    int32_t idx = node_count++;
    nodes[idx].parent = parent;
    nodes[idx].depth = nodes[parent].depth + 1;
    nodes[idx].child[0] = nodes[idx].child[1] = -1;
    nodes[idx].marked = 0;
    nodes[parent].child[bit] = idx;
    hkey[h] = key;
    htab[h] = idx + 1;
    return idx;
}

